"288 :     private void addSymbolUse(String name, JSModule module, SymbolType type) {
289 :       NameInfo info = getNameInfoForName(name, type);
290 :       NameInfo def = null;
291 :       // Skip all anonymous nodes. We care only about symbols with names.
292 :       for (int i = symbolStack.size() - 1; i >= 0; i--) {
293 :         def = symbolStack.get(i).name;
294 :         if (def != anonymousNode) {
295 :           break;
296 :         }
297 :       }
298 :       if (!def.equals(info)) {
299 :         symbolGraph.connect(def, module, info);
300 :       }
301 :     }"

